content.content:
{
  "items": [
    {
      "metadata": {
        "name": "claims-payment-system",
        "description": "Processes approved claim settlements and interim payments. Supports bank\ntransfer, cheque, and digital wallet disbursements. Enforces dual-control\napproval for payments above threshold limits.\n"
      },
      "spec": {
        "owner": "group:default/claims-engineering"
      }
    },
    {
      "metadata": {
        "name": "claims-litigation-system",
        "description": "Manages claims that escalate to legal proceedings, including solicitor\nappointment, court date tracking, subrogation recovery actions, and\ninter-company recovery workflows.\n"
      },
      "spec": {
        "owner": "group:default/claims-engineering"
      }
    },
    {
      "metadata": {
        "name": "fnol-system",
        "description": "First Notice of Loss intake and triage system. Accepts loss notifications\nfrom all channels (web, mobile, phone, third-party adjusters), validates\ncoverage, and routes claims to the appropriate assessment workflow.\n"
      },
      "spec": {
        "owner": "group:default/claims-engineering"
      }
    },
    {
      "metadata": {
        "name": "claims-assessment-system",
        "description": "Manages adjuster assignment, damage estimation, reserve calculation, and\nclaims decisioning workflows. Supports both field adjusters and desk-based\nvirtual adjustment for lower-severity claims.\n"
      },
      "spec": {
        "owner": "group:default/claims-engineering"
      }
    },
    {
      "metadata": {
        "name": "claims-document-system",
        "description": "Manages all claim-related documents including loss photographs, repair\nestimates, medical reports, witness statements, and settlement letters.\nProvides document capture, classification, and retrieval services.\n"
      },
      "spec": {
        "owner": "group:default/claims-engineering"
      }
    },
    {
      "metadata": {
        "name": "claims-fraud-detection-system",
        "description": "Real-time and batch fraud scoring for submitted claims using ML models,\nnetwork graph analysis, and third-party data enrichment. Flags suspicious\nclaims for Special Investigations Unit (SIU) review.\n"
      },
      "spec": {
        "owner": "group:default/claims-engineering"
      }
    }
  ],
  "totalItems": 6,
  "hasMoreEntities": false
}

