content.content:
{
  "items": [
    {
      "metadata": {
        "name": "refunds-adjustments-system",
        "description": "Processes premium refunds for cancellations, endorsements, and overpayments.\nManages credit note issuance, refund routing back to original payment\nmethod, and regulatory refund timeline compliance.\n"
      },
      "spec": {
        "owner": "group:default/billing-payments-engineering"
      }
    },
    {
      "metadata": {
        "name": "premium-collection-system",
        "description": "Manages the billing account lifecycle: instalment schedules, due date\nmanagement, arrears tracking, and lapse triggers. Supports annual,\nmonthly, and quarterly payment frequencies.\n"
      },
      "spec": {
        "owner": "group:default/billing-payments-engineering"
      }
    },
    {
      "metadata": {
        "name": "billing-account-system",
        "description": "Maintains the customer billing account as the financial ledger for\npremium transactions. Tracks credits, debits, instalments, fees, and\ninterest charges. Provides statements and payment history.\n"
      },
      "spec": {
        "owner": "group:default/billing-payments-engineering"
      }
    },
    {
      "metadata": {
        "name": "payment-processing-system",
        "description": "Processes inbound premium payments via direct debit, card, bank transfer,\nand digital wallets. Integrates with payment acquirers, banking partners,\nand the Bacs/SEPA payment networks.\n"
      },
      "spec": {
        "owner": "group:default/billing-payments-engineering"
      }
    }
  ],
  "totalItems": 4,
  "hasMoreEntities": false
}

