content.content:
{
  "items": [
    {
      "metadata": {
        "name": "claims-payment-disbursement-service",
        "description": "Executes approved claim payment instructions via bank transfer (BACS/\nSEPA/ACH), cheque generation, or digital wallet transfer. Enforces\ndual-control approval for payments exceeding settlement authority limits\nand maintains a full payment audit trail.\n"
      },
      "spec": {
        "type": "service",
        "lifecycle": "production",
        "owner": "group:default/claims-engineering"
      }
    },
    {
      "metadata": {
        "name": "bank-account-validation-service",
        "description": "Validates claimant and repairer bank account details before payment\nrelease. Performs sort code/routing number lookups, IBAN validation,\nand real-time account verification via Open Banking APIs. Flags\nmismatched or suspicious account details for fraud review.\n"
      },
      "spec": {
        "type": "service",
        "lifecycle": "production",
        "owner": "group:default/claims-engineering"
      }
    },
    {
      "metadata": {
        "name": "subrogation-recovery-service",
        "description": "Identifies and pursues subrogation and contribution recovery opportunities\nafter claim settlement. Tracks recovery actions against at-fault third\nparties, insurers, and manufacturers. Manages inter-company arbitration\nand recovery accounting back to the claim reserve.\n"
      },
      "spec": {
        "type": "service",
        "lifecycle": "production",
        "owner": "group:default/claims-engineering"
      }
    },
    {
      "metadata": {
        "name": "claims-settlement-service",
        "description": "Orchestrates the end-to-end settlement of approved claims. Calculates\nnet payable amounts after deductible, excess, co-insurance, and\nsubrogation recoveries. Creates payment instructions and triggers\nclaimant settlement offer communications.\n"
      },
      "spec": {
        "type": "service",
        "lifecycle": "production",
        "owner": "group:default/claims-engineering"
      }
    },
    {
      "metadata": {
        "name": "supplier-payment-service",
        "description": "Manages direct payments to approved repair garages, contractors, medical\nproviders, and legal firms. Handles supplier onboarding, purchase order\nmatching, invoice validation, and payment batch processing.\n"
      },
      "spec": {
        "type": "service",
        "lifecycle": "production",
        "owner": "group:default/claims-engineering"
      }
    }
  ],
  "totalItems": 5,
  "hasMoreEntities": false
}

