content.content:
{
  "items": [
    {
      "metadata": {
        "name": "payment-gateway-service",
        "description": "Processes inbound premium payments via card, digital wallet, and bank\ntransfer. Integrates with Worldpay and Stripe for card acquiring, and\nwith Open Banking APIs for account-to-account payments. Handles 3DS2\nauthentication, tokenisation, and payment confirmation routing.\n"
      },
      "spec": {
        "type": "service",
        "lifecycle": "production",
        "owner": "group:default/billing-payments-engineering"
      }
    },
    {
      "metadata": {
        "name": "payment-fraud-screening-service",
        "description": "Screens premium payment transactions for card fraud and money laundering\nindicators. Applies velocity rules, device fingerprinting, and behavioural\nbiometrics to flag suspicious transactions for manual review before\nsettlement is confirmed to the billing ledger.\n"
      },
      "spec": {
        "type": "service",
        "lifecycle": "production",
        "owner": "group:default/billing-payments-engineering"
      }
    },
    {
      "metadata": {
        "name": "payment-reconciliation-service",
        "description": "Reconciles inbound payment files from banks, card acquirers, and direct\ndebit clearing houses against expected premium receipts in the billing\nledger. Identifies unmatched credits, duplicate payments, and underpayments,\nand queues exceptions for the finance operations team.\n"
      },
      "spec": {
        "type": "service",
        "lifecycle": "production",
        "owner": "group:default/billing-payments-engineering"
      }
    }
  ],
  "totalItems": 3,
  "hasMoreEntities": false
}

